import { gunzipSync } from "node:zlib";
// Temp website: index.html, gzipped. Rebuilt from build.py.
const GZ = Buffer.from("", "base64");
const HTML = gunzipSync(GZ);
const headers = { "content-type": "text/html; charset=utf-8", "cache-control": "no-cache", "x-content-type-options": "nosniff", "referrer-policy": "strict-origin-when-cross-origin" };
Bun.serve({
  port: Number(Bun.env.PORT) || 3000,
  fetch(req) {
    const url = new URL(req.url);
    if (url.pathname === "/health") return new Response("ok");
    if ((req.headers.get("accept-encoding") || "").includes("gzip")) return new Response(GZ, { headers: { ...headers, "content-encoding": "gzip", vary: "accept-encoding" } });
    return new Response(HTML, { headers: { ...headers, vary: "accept-encoding" } });
  },
});
